/// Writes the generated F# files. Output is a pure function of bindings.json and the pinned headers, with LF endings.
module Lrm.Tools.D3D12Gen.Emit

open System
open System.Text
open Lrm.Tools.D3D12Gen.Header
open Lrm.Tools.D3D12Gen.Bind

type private Out() =
    let sb = StringBuilder()
    member _.Line(s: string) = sb.Append(s).Append('\n') |> ignore
    member _.Blank() = sb.Append('\n') |> ignore
    member _.Text = sb.ToString()

let private banner (m: Model) (o: Out) (what: string) =
    o.Line "// <auto-generated>"

    o.Line(
        sprintf
            "// %s, generated by tools/d3d12gen from the Windows SDK %s headers pinned in tools/d3d12gen/bindings.json."
            what
            m.Bindings.SdkVersion
    )

    o.Line "// Do not edit. Regenerate with: dotnet run --project tools/d3d12gen/Lrm.Tools.D3D12Gen -c Release"
    o.Line "// </auto-generated>"

let private guidCtor (g: Guid) =
    let b = g.ToByteArray()
    let d1 = BitConverter.ToUInt32(b, 0)
    let d2 = BitConverter.ToUInt16(b, 4)
    let d3 = BitConverter.ToUInt16(b, 6)

    sprintf
        "Guid(0x%08xu, 0x%04xus, 0x%04xus, 0x%02xuy, 0x%02xuy, 0x%02xuy, 0x%02xuy, 0x%02xuy, 0x%02xuy, 0x%02xuy, 0x%02xuy)"
        d1
        d2
        d3
        b[8]
        b[9]
        b[10]
        b[11]
        b[12]
        b[13]
        b[14]
        b[15]

let private enumLiteral (flags: bool) (v: int64) (where: string) =
    if v > 0xFFFFFFFFL || v < int64 Int32.MinValue then
        failwithf "%s: value %d does not fit a 32-bit enum" where v

    if flags then
        sprintf "0x%08X" (uint32 v)
    else
        string (int32 (uint32 (v &&& 0xFFFFFFFFL)))

let private cSignature (m: Method) =
    let ps =
        m.Params
        |> List.map (fun p -> sprintf "%s %s" (describe p.Type) p.Name)
        |> String.concat ", "

    sprintf "%s %s(%s)" (describe m.Return) m.Name ps

/// D3D12.g.fs: enums, structs, interface markers, IIDs, vtable slots and delegates.
let types (m: Model) : string =
    let o = Out()
    banner m o "Types, IIDs, vtable slots and delegates"
    o.Line "namespace Lrm.Gpu.D3D12.Interop"
    o.Blank()
    o.Line "#nowarn \"9\""
    o.Blank()
    o.Line "open System"
    o.Line "open System.Collections.Generic"
    o.Line "open System.Runtime.CompilerServices"
    o.Line "open System.Runtime.InteropServices"
    o.Blank()

    // ---- enums
    for (def, prefix, flags) in m.Enums do
        o.Line(sprintf "/// %s (%s)." def.Name (IO.Path.GetFileName def.File))

        if flags then
            o.Line(sprintf "[<Flags; CEnum(\"%s\", \"%s\")>]" def.Name prefix)
        else
            o.Line(sprintf "[<CEnum(\"%s\", \"%s\")>]" def.Name prefix)

        o.Line(sprintf "type %s =" def.Name)

        for mem in def.Members do
            match mem.Value with
            | Ok v ->
                let rest = mem.Name.Substring prefix.Length
                let name = if Char.IsDigit rest[0] then "_" + rest else rest

                o.Line(sprintf "    | %s = %s" (ident name) (enumLiteral flags v (def.Name + "." + mem.Name)))
            | Error e -> failwithf "%s.%s: %s" def.Name mem.Name e

        o.Blank()

    // ---- inline arrays and structs, in dependency order
    let arrays = m.Arrays |> List.map (fun (n, e, c, k) -> n, (e, c, k)) |> Map.ofList

    let structs = m.Structs |> List.map (fun (a, l) -> a.Name, (a, l)) |> Map.ofList

    for item in m.Order do
        match item with
        | Choice1Of2 name ->
            let (elem, cElem, count) = arrays[name]

            o.Line(
                sprintf
                    "/// %s[%d], an inline array; index it with MemoryMarshal.CreateSpan(&x.e0, %d)."
                    cElem
                    count
                    count
            )

            o.Line(sprintf "[<Struct; InlineArray(%d); CArray(\"%s\", %d)>]" count cElem count)
            o.Line(sprintf "type %s =" name)
            o.Line(sprintf "    val mutable e0: %s" elem)
            o.Blank()
        | Choice2Of2 name ->
            let (a, l) = structs[name]

            o.Line(
                sprintf
                    "/// %s (%s): %d bytes, %d-byte aligned%s."
                    a.Name
                    (IO.Path.GetFileName a.File)
                    l.Size
                    l.Align
                    (if a.IsUnion then ", a union" else "")
            )

            if l.Explicit then
                o.Line(
                    sprintf "[<Struct; StructLayout(LayoutKind.Explicit, Size = %d); CStruct(\"%s\")>]" l.Size a.Name
                )
            else
                o.Line(sprintf "[<Struct; StructLayout(LayoutKind.Sequential); CStruct(\"%s\")>]" a.Name)

            o.Line(sprintf "type %s =" a.Name)

            for f in l.Fields do
                let t = m.FsType f.Type

                if l.Explicit then
                    o.Line(sprintf "    [<FieldOffset(%d)>]" f.Offset)

                o.Line(sprintf "    val mutable %s: %s" (ident f.Name) t)

            o.Blank()

    // ---- interface markers
    for i in m.Interfaces do
        o.Line(
            sprintf
                "/// COM interface %s (%s), IID %O, %d vtable slots. A phantom type for ComPtr: it is never implemented."
                i.Name
                i.File
                i.Iid
                i.Slots.Length
        )

        match i.Base with
        | None ->
            o.Line(sprintf "type %s =" i.Name)
            o.Line "    interface"
            o.Line "    end"
        | Some b ->
            o.Line(sprintf "type %s =" i.Name)
            o.Line(sprintf "    inherit %s" b)

        o.Blank()

    // ---- IIDs
    o.Line "/// Interface IDs, from DEFINE_GUID and MIDL_INTERFACE in the headers (they must agree)."
    o.Line "[<RequireQualifiedAccess>]"
    o.Line "module Iids ="

    for i in m.Interfaces do
        o.Line(sprintf "    /// %O" i.Iid)
        o.Line(sprintf "    let %s = %s" i.Name (guidCtor i.Iid))
        o.Blank()

    o.Line "    /// Every marker type and its IID."
    o.Line "    let internal byType: IReadOnlyDictionary<Type, Guid> ="
    o.Line "        readOnlyDict"
    o.Line "            ["

    for i in m.Interfaces do
        o.Line(sprintf "                typeof<%s>, %s" i.Name i.Name)

    o.Line "            ]"
    o.Blank()

    // ---- slots
    o.Line
        "/// Vtable slots: the position of each method's DECLSPEC_XFGVIRT marker in the C vtable, inherited ones included."

    o.Line "[<RequireQualifiedAccess>]"
    o.Line "module Slots ="

    for i in m.Interfaces do
        o.Line "    [<RequireQualifiedAccess>]"
        o.Line(sprintf "    module %s =" i.Name)

        for s in i.Slots do
            o.Line "        [<Literal>]"
            o.Line(sprintf "        let %s = %d" (ident s.Name) s.Slot)

        o.Line "        /// The number of slots."
        o.Line "        [<Literal>]"
        o.Line(sprintf "        let Count = %d" i.Slots.Length)
        o.Blank()

    // ---- delegates
    o.Line
        "/// One unmanaged delegate type per bound method, in the C vtable's signature: This first, pointers as nativeint,"

    o.Line
        "/// struct returns through the hidden RetVal pointer. Call them through Vtbl.get, which caches the delegates."

    o.Line "[<RequireQualifiedAccess>]"
    o.Line "module Fn ="

    for i in m.Interfaces do
        let own =
            if i.Name = "IUnknown" then
                i.Slots
            else
                i.Own |> List.map _.Method

        if not own.IsEmpty then
            o.Line "    [<RequireQualifiedAccess>]"
            o.Line(sprintf "    module %s =" i.Name)

            for meth in own do
                let shape =
                    if i.Name = "IUnknown" then
                        None
                    else
                        i.Own |> List.tryFind (fun b -> b.Method.Name = meth.Name)

                let ps, ret =
                    match shape with
                    | Some b -> List.zip (meth.Params |> List.map _.Name) b.DelegateParams, b.DelegateReturn
                    | None ->
                        // IUnknown: QueryInterface(REFIID, void**) : HRESULT, AddRef/Release() : ULONG.
                        (meth.Params |> List.map (fun p -> p.Name, "nativeint")),
                        (if meth.Name = "QueryInterface" then "int" else "uint32")

                let args =
                    ("self", "nativeint") :: ps
                    |> List.map (fun (n, t) -> sprintf "%s: %s" (ident n) t)
                    |> String.concat " * "

                o.Line(sprintf "        /// %s (slot %d)" (cSignature meth) meth.Slot)
                o.Line "        [<UnmanagedFunctionPointer(CallingConvention.StdCall)>]"
                o.Line(sprintf "        type %s = delegate of %s -> %s" (ident meth.Name) args ret)

            o.Blank()

    o.Text.TrimEnd('\n') + "\n"

/// D3D12Methods.g.fs: typed extension methods for every method an interface declares.
let methods (m: Model) : string =
    let o = Out()
    banner m o "Typed wrappers"
    o.Line "namespace Lrm.Gpu.D3D12.Interop"
    o.Blank()
    o.Line "#nowarn \"9\""
    o.Line "#nowarn \"51\""
    o.Blank()
    o.Line "open System.Runtime.CompilerServices"
    o.Line "open Microsoft.FSharp.NativeInterop"
    o.Blank()

    for i in m.Interfaces do
        if not i.Own.IsEmpty then
            o.Line(
                sprintf
                    "/// The methods %s declares. They apply to ComPtr<'I> for %s and every interface derived from it."
                    i.Name
                    i.Name
            )

            o.Line "[<Extension; AbstractClass; Sealed>]"
            o.Line(sprintf "type %sMethods =" i.Name)

            for b in i.Own do
                let meth = b.Method
                let qualified = sprintf "%s::%s" i.Name meth.Name
                let fn = sprintf "Fn.%s.%s" i.Name (ident meth.Name)
                let slot = sprintf "Slots.%s.%s" i.Name (ident meth.Name)
                let call = sprintf "(Vtbl.get<%s> this.Ptr %s).Invoke" fn slot
                let names = meth.Params |> List.map (fun p -> ident p.Name)

                let typed = b.ReturnsHresult && not b.HresultIsValue

                // Shapes that only typed HRESULT wrappers interpret.
                let shapes =
                    b.Shapes
                    |> List.map (fun s ->
                        match s with
                        | Riid
                        | OutGeneric
                        | OutValue _
                        | OutInterface _ when not typed -> Plain
                        | s -> s)

                // ---- generic parameters and the typed parameter list
                let generics = ResizeArray<string * string>()
                generics.Add("'I", i.Name)
                let typedParams = ResizeArray<string>()
                let mutable k = 0

                for (p, s, dt) in List.zip3 meth.Params shapes b.DelegateParams do
                    match s with
                    | InterfaceIn j ->
                        let g = sprintf "'P%d" k
                        k <- k + 1
                        generics.Add(g, j)
                        typedParams.Add(sprintf "%s: ComPtr<%s>" (ident p.Name) g)
                    | WideString -> typedParams.Add(sprintf "%s: string" (ident p.Name))
                    | InStruct st -> typedParams.Add(sprintf "%s: inref<%s>" (ident p.Name) st)
                    | Plain -> typedParams.Add(sprintf "%s: %s" (ident p.Name) dt)
                    | Riid
                    | OutGeneric
                    | OutInterface _
                    | OutValue _
                    | RetVal _ -> ()

                let outGeneric = shapes |> List.contains OutGeneric

                if outGeneric then
                    generics.Add("'T", "IUnknown")

                let genericDecl (gs: (string * string) seq) =
                    let gs = List.ofSeq gs
                    let names = gs |> List.map fst |> String.concat ", "

                    let constraints =
                        gs |> List.map (fun (g, c) -> sprintf "%s :> %s" g c) |> String.concat " and "

                    sprintf "<%s when %s>" names constraints

                let returnType, retVal =
                    match shapes |> List.tryLast with
                    | Some(RetVal s) -> s, true
                    | _ ->
                        if typed then
                            if outGeneric then
                                "ComPtr<'T>", false
                            else
                                match shapes |> List.tryLast with
                                | Some(OutInterface j) -> sprintf "ComPtr<%s>" j, false
                                | Some(OutValue t) -> t, false
                                | _ -> "unit", false
                        else
                            b.DelegateReturn, false

                // ---- the argument list passed to Invoke
                let wide = ResizeArray<string * string>()
                let pinned = ResizeArray<string * string>()

                let args =
                    List.zip3 meth.Params shapes names
                    |> List.map (fun (p, s, n) ->
                        match s with
                        | InterfaceIn _ -> n + ".Ptr"
                        | WideString ->
                            let local = sprintf "w%d'" wide.Count
                            wide.Add(n, local)
                            local
                        | InStruct _ ->
                            let local = sprintf "p%d'" pinned.Count
                            pinned.Add(n, local)
                            "NativePtr.toNativeInt " + local
                        | Riid -> "NativePtr.toNativeInt &&iid'"
                        | OutGeneric
                        | OutInterface _
                        | OutValue _ -> "NativePtr.toNativeInt &&out'"
                        | RetVal _ -> "NativePtr.toNativeInt &&ret'"
                        | Plain -> n)

                let invoke =
                    sprintf "%s(this.Ptr%s)" call (args |> List.map (fun a -> ", " + a) |> String.concat "")

                let invokeWithStrings =
                    // Pin each string for the duration of the call.
                    wide
                    |> Seq.rev
                    |> Seq.fold (fun inner (n, local) -> sprintf "Com.withWide %s (fun %s -> %s)" n local inner) invoke

                o.Line(sprintf "    /// %s (slot %d): %s." qualified meth.Slot (cSignature meth))

                if typed then
                    o.Line
                        "    /// Raises D3D12Exception, with the device-removed reason, when the HRESULT is a failure."

                o.Line "    [<Extension>]"

                o.Line(
                    sprintf
                        "    static member %s%s(%s) : %s ="
                        (ident b.WrapperName)
                        (genericDecl generics)
                        (("this: ComPtr<'I>" :: List.ofSeq typedParams) |> String.concat ", ")
                        returnType
                )

                if outGeneric then
                    o.Line "        let mutable iid' = IidOf<'T>.Value"

                if
                    shapes
                    |> List.exists (function
                        | OutGeneric
                        | OutInterface _ -> true
                        | _ -> false)
                then
                    o.Line "        let mutable out' = 0n"

                match shapes |> List.tryLast with
                | Some(OutValue t) -> o.Line(sprintf "        let mutable out' = Unchecked.defaultof<%s>" t)
                | _ -> ()

                for (n, local) in pinned do
                    o.Line(sprintf "        use %s = fixed &%s" local n)

                if retVal then
                    o.Line(sprintf "        let mutable ret' = Unchecked.defaultof<%s>" returnType)
                    o.Line(sprintf "        %s |> ignore" invokeWithStrings)
                    o.Line "        ret'"
                elif typed then
                    o.Line(sprintf "        let hr' = %s" invokeWithStrings)
                    o.Line(sprintf "        Com.check \"%s\" hr' this.Ptr" qualified)

                    if outGeneric then
                        o.Line "        ComPtr<'T>.Attach out'"
                    else
                        match shapes |> List.tryLast with
                        | Some(OutInterface j) -> o.Line(sprintf "        ComPtr<%s>.Attach out'" j)
                        | Some(OutValue _) -> o.Line "        out'"
                        | _ -> ()
                else
                    o.Line(sprintf "        %s" invokeWithStrings)

                o.Blank()

                // ---- the raw form of HRESULT methods: the delegate's own parameters, the HRESULT returned
                if typed then
                    o.Line(
                        sprintf
                            "    /// %s (slot %d), raw: the C parameters as passed, the HRESULT returned."
                            qualified
                            meth.Slot
                    )

                    o.Line "    [<Extension>]"

                    let rawParams =
                        List.zip names b.DelegateParams |> List.map (fun (n, t) -> sprintf "%s: %s" n t)

                    o.Line(
                        sprintf
                            "    static member %sRaw<'I when 'I :> %s>(%s) : int ="
                            b.WrapperName
                            i.Name
                            (("this: ComPtr<'I>" :: rawParams) |> String.concat ", ")
                    )

                    o.Line(
                        sprintf
                            "        %s(this.Ptr%s)"
                            call
                            (names |> List.map (fun a -> ", " + a) |> String.concat "")
                    )

                    o.Blank()

    o.Text.TrimEnd('\n') + "\n"
